const BuiltinFamilyDescriptorCount = len(builtinFamilyRows) + len(builtinFamilyOperators) + len(builtinFamilySupports)

var builtinFamilyOperatorKeys = func() [len(builtinFamilyOperators)]ids.NameKey {
	var keys [len(builtinFamilyOperators)]ids.NameKey
	for i := range keys {
		d := &builtinFamilyOperators[i]
		d.InternalOwner = builtinMemberInternalOwner(d.Method, d.Family, d.Left, d.Right, d.Number, false)
		keys[i] = DescriptorNameKey(d)
	}
	return keys
}()
var builtinFamilySupportKeys = func() [len(builtinFamilySupports)]ids.NameKey {
	var keys [len(builtinFamilySupports)]ids.NameKey
	for i := range keys {
		d := &builtinFamilySupports[i]
		_, d.CatalogVisible = sqltype.NativeIndexRoutineByOID(uint32(d.Function))
		for _, operation := range brinSupportDeclarations {
			if operation.oid == d.Function {
				d.CatalogVisible = true
				break
			}
		}
		for _, family := range builtinFamilyRows {
			if family.oid == d.Family {
				d.InternalOwner = builtinMemberInternalOwner(family.method, d.Family, d.Left, d.Right, d.Number, true)
				break
			}
		}
		keys[i] = DescriptorNameKey(d)
	}
	return keys
}()

var builtinFamilyKeys = func() [len(builtinFamilyRows)]ids.NameKey {
	var keys [len(builtinFamilyRows)]ids.NameKey
	for i, row := range builtinFamilyRows {
		keys[i] = FamilyNameKey(ids.ObjectAddress{ClassID: ids.NamespaceClassID, ObjectID: ids.PGCatalogNamespaceOID}, row.method, row.name)
	}
	return keys
}()

// InstallBuiltinFamilies installs immutable compiled members and engine-owned
// family owner references into a private bootstrap state.
func InstallBuiltinFamilies(state *State, owner authorization.PrincipalRef) {
	families := make([]OperatorFamily, len(builtinFamilyRows))
	for i, row := range builtinFamilyRows {
		d := &families[i]
		*d = OperatorFamily{ObjectAddress: ids.ObjectAddress{ClassID: ids.OperatorFamilyClassID, ObjectID: row.oid}, ObjectNamespace: ids.ObjectAddress{ClassID: ids.NamespaceClassID, ObjectID: ids.PGCatalogNamespaceOID}, ObjectRevision: 1, ObjectName: row.name, Method: row.method, Owner: owner}
		state.addSeedDescriptor(d.Address(), d)
		state.bindSeedKey(builtinFamilyKeys[i], d.Address())
	}
	for i := range builtinFamilyOperators {
		d := &builtinFamilyOperators[i]
		state.addSeedDescriptor(d.Address(), d)
		state.bindSeedKey(builtinFamilyOperatorKeys[i], d.Address())
	}
	for i := range builtinFamilySupports {
		d := &builtinFamilySupports[i]
		state.addSeedDescriptor(d.Address(), d)
		state.bindSeedKey(builtinFamilySupportKeys[i], d.Address())
	}
}
